import numpy as np

def heuristic(dist_m, turn_deg, swath_len_m, energy_left_frac, depot_dist_m, fits):
    # Filter infeasible routes (must swap battery) with a zero score;
    # feasible routes score strictly by inverse transit distance to guide pheromone learning.
    base_score = 1.0 / (dist_m + 1e-6)
    return np.where(fits == 1.0, base_score, 0.0)

